from backend.modules.db_simulator.query_library.builder import q
_C = "COALESCE(C.NOMBRECOMERCIAL, C.RAZONSOCIAL, CAST(D.CODCLIENTE AS TEXT))"
_A = "COALESCE(A.NOMBRE, A.DESCRIPCION, L.CODARTICULO)"

QUERIES_SAT_EXTENDED = [
    q("sx_001","Total de SATs por anio","Cuantos SATs se han generado cada anio?","COUNT de DOCCAB TIPO=2 por anio.","SELECT SUBSTR(FECHA,1,4) AS ANIO, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4) ORDER BY ANIO DESC","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_002","Total de SATs por mes","Cuantos SATs se han generado cada mes?","COUNT de DOCCAB TIPO=2 por mes.","SELECT SUBSTR(FECHA,1,7) AS MES, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,7) ORDER BY MES DESC LIMIT 24","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_003","Total de SATs del mes actual","Cuantos SATs hay este mes?","COUNT de DOCCAB TIPO=2 del mes actual.","SELECT COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now')","SAT / Tecnico","Tecnico","KPI","Critico","SATs mes",""),
    q("sx_004","Total de SATs del anio actual","Cuantos SATs hay este anio?","COUNT de DOCCAB TIPO=2 del anio actual.","SELECT COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND SUBSTR(FECHA,1,4)=strftime('%Y','now')","SAT / Tecnico","Tecnico","KPI","Critico","SATs anio",""),
    q("sx_005","Clientes con mas SATs","Que clientes generan mas SATs?","COUNT de DOCCAB TIPO=2 por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_SATS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 GROUP BY D.CODCLIENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Cliente","Alto","",""),
    q("sx_006","Clientes con mayor importe en SATs","Que clientes generan mas importe en SATs?","SUM(IMPORTETOTAL) de DOCCAB TIPO=2 por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_SATS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 GROUP BY D.CODCLIENTE ORDER BY TOTAL DESC LIMIT 20","SAT / Tecnico","Tecnico","Cliente","Alto","",""),
    q("sx_007","Articulos mas usados en SATs","Que articulos aparecen mas en SATs?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 por articulo.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)),2) AS CANTIDAD FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_008","Articulos con mayor importe en SATs","Que articulos generan mas importe en SATs?","SUM(CANTIDAD*PRECIO) de DOCLIN JOIN DOCCAB TIPO=2 por articulo.","SELECT "+_A+" AS ARTICULO, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO GROUP BY L.CODARTICULO ORDER BY IMPORTE DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_009","SATs por agente tecnico","Cuantos SATs gestiona cada agente?","COUNT de DOCCAB TIPO=2 por CODAGENTE.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_010","SATs por agente tecnico en el mes actual","Cuantos SATs gestiona cada agente este mes?","COUNT de DOCCAB TIPO=2 del mes actual por CODAGENTE.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now') AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Critico","",""),
    q("sx_011","SATs por agente tecnico en el anio actual","Cuantos SATs gestiona cada agente este anio?","COUNT de DOCCAB TIPO=2 del anio actual por CODAGENTE.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND SUBSTR(FECHA,1,4)=strftime('%Y','now') AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_012","Ticket medio de SAT por anio","Cual es el ticket medio de SAT de cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio.","SELECT SUBSTR(FECHA,1,4) AS ANIO, ROUND(AVG(IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4) ORDER BY ANIO DESC","SAT / Tecnico","Tecnico","KPI","Medio","",""),
    q("sx_013","Ticket medio de SAT por mes","Cual es el ticket medio de SAT de cada mes?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por mes.","SELECT SUBSTR(FECHA,1,7) AS MES, ROUND(AVG(IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,7) ORDER BY MES DESC LIMIT 24","SAT / Tecnico","Tecnico","KPI","Medio","",""),
    q("sx_014","SATs con mayor importe","Cuales son los SATs de mayor importe?","DOCCAB TIPO=2 ordenado por IMPORTETOTAL DESC.","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, ROUND(D.IMPORTETOTAL,2) AS IMPORTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 ORDER BY D.IMPORTETOTAL DESC LIMIT 20","SAT / Tecnico","Tecnico","Financiero","Alto","",""),
    q("sx_015","SATs con importe cero","Hay SATs con importe cero?","DOCCAB TIPO=2 con IMPORTETOTAL=0 o NULL.","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND (D.IMPORTETOTAL=0 OR D.IMPORTETOTAL IS NULL) LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Medio","",""),
    q("sx_016","SATs sin cliente asignado","Hay SATs sin cliente asignado?","DOCCAB TIPO=2 con CODCLIENTE NULL o 0.","SELECT COUNT(*) AS N_SIN_CLIENTE FROM DOCCAB WHERE TIPO=2 AND (CODCLIENTE IS NULL OR CODCLIENTE=0)","SAT / Tecnico","Tecnico","Calidad","Alto","",""),
    q("sx_017","SATs sin agente asignado","Hay SATs sin agente asignado?","DOCCAB TIPO=2 con CODAGENTE NULL o 0.","SELECT COUNT(*) AS N_SIN_AGENTE FROM DOCCAB WHERE TIPO=2 AND (CODAGENTE IS NULL OR CODAGENTE=0)","SAT / Tecnico","Tecnico","Calidad","Medio","",""),
    q("sx_018","SATs sin lineas de detalle","Hay SATs sin lineas de detalle?","DOCCAB TIPO=2 que no tienen registros en DOCLIN.","SELECT COUNT(*) AS N_SIN_LINEAS FROM DOCCAB D WHERE D.TIPO=2 AND CODIGO NOT IN (SELECT DISTINCT CODDOCUMENTO FROM DOCLIN WHERE CODDOCUMENTO IS NOT NULL)","SAT / Tecnico","Tecnico","Calidad","Medio","",""),
    q("sx_019","SATs con fecha futura","Hay SATs con fecha futura?","DOCCAB TIPO=2 con FECHA > date('now').","SELECT COUNT(*) AS N_FECHA_FUTURA FROM DOCCAB WHERE TIPO=2 AND FECHA > date('now')","SAT / Tecnico","Tecnico","Calidad","Alto","",""),
    q("sx_020","SATs con fecha anterior a 2020","Hay SATs con fecha anterior a 2020?","DOCCAB TIPO=2 con FECHA < '2020-01-01'.","SELECT COUNT(*) AS N_FECHA_ANTIGUA FROM DOCCAB WHERE TIPO=2 AND FECHA < '2020-01-01'","SAT / Tecnico","Tecnico","Calidad","Bajo","",""),
    q("sx_021","SATs por estado","Cuantos SATs hay en cada estado?","COUNT de DOCCAB TIPO=2 por ESTADO.","SELECT COALESCE(CAST(ESTADO AS TEXT),'Sin estado') AS ESTADO, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 GROUP BY ESTADO ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Alto","",""),
    q("sx_022","SATs pendientes (estado 0)","Cuantos SATs estan pendientes?","COUNT de DOCCAB TIPO=2 con ESTADO=0.","SELECT COUNT(*) AS N_PENDIENTES, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL_PENDIENTE FROM DOCCAB WHERE TIPO=2 AND (ESTADO=0 OR ESTADO IS NULL)","SAT / Tecnico","Tecnico","KPI","Critico","SATs pendientes",""),
    q("sx_023","SATs cerrados (estado 1)","Cuantos SATs estan cerrados?","COUNT de DOCCAB TIPO=2 con ESTADO=1.","SELECT COUNT(*) AS N_CERRADOS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL_CERRADO FROM DOCCAB WHERE TIPO=2 AND ESTADO=1","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_024","Ratio SATs cerrados vs pendientes","Que porcentaje de SATs estan cerrados?","COUNT de DOCCAB TIPO=2 con ESTADO=1 vs ESTADO=0.","SELECT SUM(CASE WHEN ESTADO=1 THEN 1 ELSE 0 END) AS CERRADOS, SUM(CASE WHEN ESTADO=0 OR ESTADO IS NULL THEN 1 ELSE 0 END) AS PENDIENTES, COUNT(*) AS TOTAL, ROUND(100.0*SUM(CASE WHEN ESTADO=1 THEN 1 ELSE 0 END)/COUNT(*),1) AS PCT_CERRADOS FROM DOCCAB WHERE TIPO=2","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_025","SATs pendientes con mas de 7 dias","Que SATs llevan mas de 7 dias pendientes?","DOCCAB TIPO=2 con ESTADO=0 y FECHA < date('now','-7 days').","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, ROUND(D.IMPORTETOTAL,2) AS IMPORTE, CAST(JULIANDAY('now')-JULIANDAY(D.FECHA) AS INTEGER) AS DIAS_PENDIENTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND (D.ESTADOPEND=0 OR D.ESTADOPEND IS NULL) AND D.FECHA < date('now','-7 days') ORDER BY DIAS_PENDIENTE DESC LIMIT 30","SAT / Tecnico","Tecnico","Riesgo","Critico","",""),
    q("sx_026","SATs pendientes con mas de 30 dias","Que SATs llevan mas de 30 dias pendientes?","DOCCAB TIPO=2 con ESTADO=0 y FECHA < date('now','-30 days').","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, ROUND(D.IMPORTETOTAL,2) AS IMPORTE, CAST(JULIANDAY('now')-JULIANDAY(D.FECHA) AS INTEGER) AS DIAS_PENDIENTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND (D.ESTADOPEND=0 OR D.ESTADOPEND IS NULL) AND D.FECHA < date('now','-30 days') ORDER BY DIAS_PENDIENTE DESC LIMIT 30","SAT / Tecnico","Tecnico","Riesgo","Critico","",""),
    q("sx_027","SATs pendientes con mas de 60 dias","Que SATs llevan mas de 60 dias pendientes?","DOCCAB TIPO=2 con ESTADO=0 y FECHA < date('now','-60 days').","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, ROUND(D.IMPORTETOTAL,2) AS IMPORTE, CAST(JULIANDAY('now')-JULIANDAY(D.FECHA) AS INTEGER) AS DIAS_PENDIENTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND (D.ESTADOPEND=0 OR D.ESTADOPEND IS NULL) AND D.FECHA < date('now','-60 days') ORDER BY DIAS_PENDIENTE DESC LIMIT 30","SAT / Tecnico","Tecnico","Riesgo","Critico","",""),
    q("sx_028","SATs por dia de la semana","Que dias de la semana se generan mas SATs?","COUNT de DOCCAB TIPO=2 por dia de la semana.","SELECT CASE CAST(strftime('%w',FECHA) AS INTEGER) WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Lunes' WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miercoles' WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' ELSE 'Sabado' END AS DIA, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY strftime('%w',FECHA) ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_029","SATs por mes del anio (estacionalidad)","Que meses del anio se generan mas SATs?","COUNT de DOCCAB TIPO=2 por mes del anio (1-12).","SELECT CAST(strftime('%m',FECHA) AS INTEGER) AS MES_NUM, CASE CAST(strftime('%m',FECHA) AS INTEGER) WHEN 1 THEN 'Enero' WHEN 2 THEN 'Febrero' WHEN 3 THEN 'Marzo' WHEN 4 THEN 'Abril' WHEN 5 THEN 'Mayo' WHEN 6 THEN 'Junio' WHEN 7 THEN 'Julio' WHEN 8 THEN 'Agosto' WHEN 9 THEN 'Septiembre' WHEN 10 THEN 'Octubre' WHEN 11 THEN 'Noviembre' ELSE 'Diciembre' END AS MES_NOMBRE, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY MES_NUM ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Medio","Estacionalidad SAT",""),
    q("sx_030","SATs por trimestre del anio (estacionalidad)","Que trimestres del anio se generan mas SATs?","COUNT de DOCCAB TIPO=2 por trimestre del anio (1-4).","SELECT ((CAST(SUBSTR(FECHA,6,2) AS INTEGER)-1)/3+1) AS TRIMESTRE, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY TRIMESTRE ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Medio","",""),
    q("sx_031","SATs por forma de pago","Cuantos SATs usan cada forma de pago?","COUNT de DOCCAB TIPO=2 por CODFORMAPAGO.","SELECT COALESCE(CODFORMAPAGO,'Sin forma pago') AS FORMA_PAGO, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 GROUP BY CODFORMAPAGO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Financiero","Bajo","",""),
    q("sx_032","SATs con mayor numero de lineas","Que SATs tienen mas lineas de detalle?","COUNT de DOCLIN por CODDOCUMENTO en DOCCAB TIPO=2.","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, COUNT(L.CODARTICULO) AS N_LINEAS, ROUND(D.IMPORTETOTAL,2) AS IMPORTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO LEFT JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=2 GROUP BY D.CODIGO ORDER BY N_LINEAS DESC LIMIT 20","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_033","SATs con una sola linea","Cuantos SATs tienen solo una linea de detalle?","COUNT de DOCCAB TIPO=2 con exactamente 1 linea en DOCLIN.","SELECT COUNT(*) AS N_SAT_UNA_LINEA FROM DOCCAB D WHERE D.TIPO=2 AND (SELECT COUNT(*) FROM DOCLIN L WHERE L.CODDOCUMENTO=CODIGO)=1","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_034","SATs con mas de 5 lineas","Cuantos SATs tienen mas de 5 lineas de detalle?","COUNT de DOCCAB TIPO=2 con mas de 5 lineas en DOCLIN.","SELECT COUNT(*) AS N_SAT_MAS_5_LINEAS FROM DOCCAB D WHERE D.TIPO=2 AND (SELECT COUNT(*) FROM DOCLIN L WHERE L.CODDOCUMENTO=CODIGO)>5","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_035","SATs con mas de 10 lineas","Cuantos SATs tienen mas de 10 lineas de detalle?","COUNT de DOCCAB TIPO=2 con mas de 10 lineas en DOCLIN.","SELECT COUNT(*) AS N_SAT_MAS_10_LINEAS FROM DOCCAB D WHERE D.TIPO=2 AND (SELECT COUNT(*) FROM DOCLIN L WHERE L.CODDOCUMENTO=CODIGO)>10","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_036","Clientes con SATs pero sin facturas","Que clientes tienen SATs pero no tienen facturas?","Clientes en DOCCAB TIPO=2 que no aparecen en DOCCAB TIPO=13.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_SATS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.CODCLIENTE NOT IN (SELECT DISTINCT CODCLIENTE FROM DOCCAB WHERE TIPO=13 AND CODCLIENTE IS NOT NULL) GROUP BY D.CODCLIENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Cliente","Medio","",""),
    q("sx_037","Clientes con SATs y facturas","Que clientes tienen tanto SATs como facturas?","Clientes en DOCCAB TIPO=2 que tambien aparecen en DOCCAB TIPO=13.","SELECT "+_C+" AS CLIENTE, SUM(CASE WHEN D.TIPO=2 THEN 1 ELSE 0 END) AS N_SATS, SUM(CASE WHEN D.TIPO=13 THEN 1 ELSE 0 END) AS N_FACTURAS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO IN (2,13) GROUP BY D.CODCLIENTE HAVING N_SATS>0 AND N_FACTURAS>0 ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Cliente","Medio","",""),
    q("sx_038","Ratio SATs por factura por cliente","Cuantos SATs genera cada cliente por cada factura?","Ratio N_SATS/N_FACTURAS por cliente.","SELECT "+_C+" AS CLIENTE, SUM(CASE WHEN D.TIPO=2 THEN 1 ELSE 0 END) AS N_SATS, SUM(CASE WHEN D.TIPO=13 THEN 1 ELSE 0 END) AS N_FACTURAS, ROUND(CAST(SUM(CASE WHEN D.TIPO=2 THEN 1 ELSE 0 END) AS REAL)/NULLIF(SUM(CASE WHEN D.TIPO=13 THEN 1 ELSE 0 END),0),2) AS RATIO_SAT_FACTURA FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO IN (2,13) GROUP BY D.CODCLIENTE HAVING N_FACTURAS>0 ORDER BY RATIO_SAT_FACTURA DESC LIMIT 20","SAT / Tecnico","Tecnico","Cliente","Alto","",""),
    q("sx_039","Importe SATs vs importe facturas por cliente","Que porcentaje del importe facturado representa el SAT por cliente?","Ratio SUM(IMPORTETOTAL TIPO=2)/SUM(IMPORTETOTAL TIPO=13) por cliente.","SELECT "+_C+" AS CLIENTE, ROUND(SUM(CASE WHEN D.TIPO=2 THEN D.IMPORTETOTAL ELSE 0 END),2) AS IMPORTE_SAT, ROUND(SUM(CASE WHEN D.TIPO=13 THEN D.IMPORTETOTAL ELSE 0 END),2) AS IMPORTE_FACTURA, ROUND(100.0*SUM(CASE WHEN D.TIPO=2 THEN D.IMPORTETOTAL ELSE 0 END)/NULLIF(SUM(CASE WHEN D.TIPO=13 THEN D.IMPORTETOTAL ELSE 0 END),0),1) AS PCT_SAT_FACTURA FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO IN (2,13) GROUP BY D.CODCLIENTE HAVING IMPORTE_FACTURA>0 ORDER BY PCT_SAT_FACTURA DESC LIMIT 20","SAT / Tecnico","Tecnico","Financiero","Alto","",""),
    q("sx_040","SATs por codigo postal del cliente","Que zonas geograficas generan mas SATs?","COUNT de DOCCAB TIPO=2 por codigo postal del cliente.","SELECT COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_SATS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 GROUP BY C.CP ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Geografico","Medio","",""),
    q("sx_041","SATs por provincia del cliente","Que provincias generan mas SATs?","COUNT de DOCCAB TIPO=2 por provincia del cliente.","SELECT COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_SATS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 GROUP BY C.CP ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Geografico","Medio","",""),
    q("sx_042","SATs del mes actual por cliente","Que clientes tienen SATs este mes?","COUNT de DOCCAB TIPO=2 del mes actual por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_SATS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') GROUP BY D.CODCLIENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Cliente","Alto","",""),
    q("sx_043","SATs del anio actual por cliente","Que clientes tienen SATs este anio?","COUNT de DOCCAB TIPO=2 del anio actual por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_SATS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND SUBSTR(D.FECHA,1,4)=strftime('%Y','now') GROUP BY D.CODCLIENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Cliente","Alto","",""),
    q("sx_044","SATs del trimestre actual por cliente","Que clientes tienen SATs en los ultimos 3 meses?","COUNT de DOCCAB TIPO=2 con FECHA>=date('now','-90 days') por cliente.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_SATS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.FECHA>=date('now','-90 days') GROUP BY D.CODCLIENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Cliente","Alto","",""),
    q("sx_045","SATs del mes actual por agente","Que agentes tienen SATs este mes?","COUNT de DOCCAB TIPO=2 del mes actual por CODAGENTE.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now') AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Critico","",""),
    q("sx_046","SATs del anio actual por agente","Que agentes tienen SATs este anio?","COUNT de DOCCAB TIPO=2 del anio actual por CODAGENTE.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND SUBSTR(FECHA,1,4)=strftime('%Y','now') AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_047","SATs del trimestre actual por agente","Que agentes tienen SATs en los ultimos 3 meses?","COUNT de DOCCAB TIPO=2 con FECHA>=date('now','-90 days') por CODAGENTE.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND FECHA>=date('now','-90 days') AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_048","SATs del mes actual por articulo","Que articulos aparecen en SATs este mes?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 del mes actual por articulo.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)),2) AS CANTIDAD FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_049","SATs del anio actual por articulo","Que articulos aparecen en SATs este anio?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 del anio actual por articulo.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)),2) AS CANTIDAD FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE SUBSTR(D.FECHA,1,4)=strftime('%Y','now') GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_050","SATs del trimestre actual por articulo","Que articulos aparecen en SATs en los ultimos 3 meses?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 con FECHA>=date('now','-90 days') por articulo.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)),2) AS CANTIDAD FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE D.FECHA>=date('now','-90 days') GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_051","SATs por familia de articulo","Que familias de articulo generan mas SATs?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 por familia.","SELECT COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO GROUP BY A.CODFAMILIA ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_052","SATs por familia de articulo en el anio actual","Que familias de articulo generan mas SATs este anio?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 del anio actual por familia.","SELECT COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO WHERE SUBSTR(D.FECHA,1,4)=strftime('%Y','now') GROUP BY A.CODFAMILIA ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_053","SATs por familia de articulo en el mes actual","Que familias de articulo generan mas SATs este mes?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 del mes actual por familia.","SELECT COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO WHERE SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') GROUP BY A.CODFAMILIA ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_054","SATs por proveedor de articulo","Que proveedores tienen mas articulos en SATs?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 por proveedor.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Proveedor","Alto","",""),
    q("sx_055","SATs por proveedor de articulo en el anio actual","Que proveedores tienen mas articulos en SATs este anio?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 del anio actual por proveedor.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO WHERE SUBSTR(D.FECHA,1,4)=strftime('%Y','now') GROUP BY A.PROVEEDDEFECTO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Proveedor","Alto","",""),
    q("sx_056","SATs por proveedor de articulo en el mes actual","Que proveedores tienen mas articulos en SATs este mes?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 del mes actual por proveedor.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO WHERE SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') GROUP BY A.PROVEEDDEFECTO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Proveedor","Alto","",""),
    q("sx_057","SATs con articulos de alta rotacion en ventas","Que articulos mas vendidos tambien aparecen en SATs?","Articulos en DOCLIN JOIN DOCCAB TIPO=2 que tambien estan en TIPO=13.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT CASE WHEN D.TIPO=2 THEN L.CODDOCUMENTO END) AS N_SATS, COUNT(DISTINCT CASE WHEN D.TIPO=13 THEN L.CODDOCUMENTO END) AS N_FACTURAS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO IN (2,13) LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO GROUP BY L.CODARTICULO HAVING N_SATS>0 AND N_FACTURAS>0 ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_058","SATs con articulos que no se venden","Que articulos aparecen en SATs pero no en facturas?","Articulos en DOCLIN JOIN DOCCAB TIPO=2 que no aparecen en TIPO=13.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE L.CODARTICULO NOT IN (SELECT DISTINCT L2.CODIGO FROM DOCLIN L2 JOIN DOCCAB D2 ON L2.CODDOCUMENTO=D2.CODIGO AND D2.TIPO=13 WHERE L2.CODIGO IS NOT NULL) GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Medio","",""),
    q("sx_059","SATs con articulos de STOCKARTICULO bajo","Que articulos con STOCKARTICULO bajo (<=3) aparecen en SATs?","Articulos en DOCLIN JOIN DOCCAB TIPO=2 con STOCKARTICULO<=3.","SELECT "+_A+" AS ARTICULO, A.STOCKARTICULO AS STOCKARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE A.STOCKARTICULO<=3 AND A.STOCKARTICULO>=0 GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Riesgo","Alto","",""),
    q("sx_060","SATs con articulos sin STOCKARTICULO","Que articulos sin STOCKARTICULO aparecen en SATs?","Articulos en DOCLIN JOIN DOCCAB TIPO=2 con STOCKARTICULO=0.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE A.STOCKARTICULO=0 GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Riesgo","Critico","",""),
    q("sx_061","SATs con articulos dados de baja","Que articulos dados de baja aparecen en SATs?","Articulos en DOCLIN JOIN DOCCAB TIPO=2 con BAJA=1.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE A.BAJA=1 GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Alto","",""),
    q("sx_062","SATs con articulos sin proveedor","Que articulos sin proveedor aparecen en SATs?","Articulos en DOCLIN JOIN DOCCAB TIPO=2 con PROVEEDDEFECTO NULL o vacio.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE A.PROVEEDDEFECTO IS NULL OR A.PROVEEDDEFECTO='' GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Medio","",""),
    q("sx_063","SATs con articulos sin familia","Que articulos sin familia aparecen en SATs?","Articulos en DOCLIN JOIN DOCCAB TIPO=2 con CODFAMILIA NULL o vacio.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE A.CODFAMILIA IS NULL OR A.CODFAMILIA='' GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Bajo","",""),
    q("sx_064","SATs con articulos con margen negativo","Que articulos con margen negativo aparecen en SATs?","Articulos en DOCLIN JOIN DOCCAB TIPO=2 con PRECIO < PRECIOCOSTE.","SELECT "+_A+" AS ARTICULO, ROUND(A.PRECIOVENTA,2) AS PRECIO, ROUND(A.PRECIOCOSTE,2) AS COSTE, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE A.PRECIOVENTA < A.PRECIOCOSTE AND A.PRECIOCOSTE>0 GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Riesgo","Alto","",""),
    q("sx_065","SATs con articulos con PRECIO cero","Que articulos con PRECIO cero aparecen en SATs?","Articulos en DOCLIN JOIN DOCCAB TIPO=2 con PRECIO=0.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE A.PRECIOVENTA=0 OR A.PRECIOVENTA IS NULL GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Medio","",""),
    q("sx_066","SATs con articulos con PRECIOCOSTE cero","Que articulos con PRECIOCOSTE cero aparecen en SATs?","Articulos en DOCLIN JOIN DOCCAB TIPO=2 con PRECIOCOSTE=0.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE A.PRECIOCOSTE=0 OR A.PRECIOCOSTE IS NULL GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Bajo","",""),
    q("sx_067","SATs con lineas de cantidad negativa","Hay SATs con lineas de cantidad negativa?","DOCLIN JOIN DOCCAB TIPO=2 con CANTIDAD < 0.","SELECT L.CODDOCUMENTO, "+_A+" AS ARTICULO, CAST(L.CANTIDAD AS REAL) AS CANTIDAD FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE CAST(L.CANTIDAD AS REAL) < 0 LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Alto","",""),
    q("sx_068","SATs con lineas de PRECIO negativo","Hay SATs con lineas de PRECIO negativo?","DOCLIN JOIN DOCCAB TIPO=2 con PRECIO < 0.","SELECT L.CODDOCUMENTO, "+_A+" AS ARTICULO, CAST(L.PRECIO AS REAL) AS PRECIO FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE CAST(L.PRECIO AS REAL) < 0 LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Critico","",""),
    q("sx_069","SATs con lineas de cantidad cero","Hay SATs con lineas de cantidad cero?","DOCLIN JOIN DOCCAB TIPO=2 con CANTIDAD=0 o NULL.","SELECT L.CODDOCUMENTO, "+_A+" AS ARTICULO FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE CAST(L.CANTIDAD AS REAL)=0 OR L.CANTIDAD IS NULL LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Medio","",""),
    q("sx_070","SATs con lineas de PRECIO cero","Hay SATs con lineas de PRECIO cero?","DOCLIN JOIN DOCCAB TIPO=2 con PRECIO=0 o NULL.","SELECT L.CODDOCUMENTO, "+_A+" AS ARTICULO, CAST(L.CANTIDAD AS REAL) AS CANTIDAD FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE CAST(L.PRECIO AS REAL)=0 OR L.PRECIO IS NULL LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Medio","",""),
    q("sx_071","SATs con articulo duplicado en la misma orden","Hay SATs con el mismo articulo repetido en la misma orden?","DOCLIN JOIN DOCCAB TIPO=2 con mismo CODDOCUMENTO y CODIGO mas de una vez.","SELECT CODDOCUMENTO, CODIGO, COUNT(*) AS N_LINEAS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 WHERE L.CODIGO IS NOT NULL AND CODIGO!='' GROUP BY CODDOCUMENTO, L.CODIGO HAVING COUNT(*)>1 ORDER BY N_LINEAS DESC LIMIT 20","SAT / Tecnico","Tecnico","Calidad","Medio","",""),
    q("sx_072","SATs con importe superior a 5000 euros","Que SATs tienen importe superior a 5000 euros?","DOCCAB TIPO=2 con IMPORTETOTAL > 5000.","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, ROUND(D.IMPORTETOTAL,2) AS IMPORTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.IMPORTETOTAL > 5000 ORDER BY D.IMPORTETOTAL DESC LIMIT 20","SAT / Tecnico","Tecnico","Financiero","Alto","",""),
    q("sx_073","SATs con importe superior a 1000 euros","Que SATs tienen importe superior a 1000 euros?","DOCCAB TIPO=2 con IMPORTETOTAL > 1000.","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, ROUND(D.IMPORTETOTAL,2) AS IMPORTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.IMPORTETOTAL > 1000 ORDER BY D.IMPORTETOTAL DESC LIMIT 20","SAT / Tecnico","Tecnico","Financiero","Medio","",""),
    q("sx_074","SATs con importe inferior a 100 euros","Que SATs tienen importe inferior a 100 euros?","DOCCAB TIPO=2 con IMPORTETOTAL < 100 y > 0.","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, ROUND(D.IMPORTETOTAL,2) AS IMPORTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.IMPORTETOTAL < 100 AND D.IMPORTETOTAL > 0 ORDER BY D.IMPORTETOTAL ASC LIMIT 20","SAT / Tecnico","Tecnico","Financiero","Bajo","",""),
    q("sx_075","SATs con importe entre 100 y 500 euros","Que SATs tienen importe entre 100 y 500 euros?","DOCCAB TIPO=2 con IMPORTETOTAL BETWEEN 100 AND 500.","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, ROUND(D.IMPORTETOTAL,2) AS IMPORTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.IMPORTETOTAL BETWEEN 100 AND 500 ORDER BY D.IMPORTETOTAL DESC LIMIT 20","SAT / Tecnico","Tecnico","Financiero","Bajo","",""),
    q("sx_076","SATs con importe entre 500 y 1000 euros","Que SATs tienen importe entre 500 y 1000 euros?","DOCCAB TIPO=2 con IMPORTETOTAL BETWEEN 500 AND 1000.","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, ROUND(D.IMPORTETOTAL,2) AS IMPORTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.IMPORTETOTAL BETWEEN 500 AND 1000 ORDER BY D.IMPORTETOTAL DESC LIMIT 20","SAT / Tecnico","Tecnico","Financiero","Bajo","",""),
    q("sx_077","SATs con importe entre 1000 y 5000 euros","Que SATs tienen importe entre 1000 y 5000 euros?","DOCCAB TIPO=2 con IMPORTETOTAL BETWEEN 1000 AND 5000.","SELECT D.CODIGO, "+_C+" AS CLIENTE, D.FECHA, ROUND(D.IMPORTETOTAL,2) AS IMPORTE FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.IMPORTETOTAL BETWEEN 1000 AND 5000 ORDER BY D.IMPORTETOTAL DESC LIMIT 20","SAT / Tecnico","Tecnico","Financiero","Medio","",""),
    q("sx_078","SATs por rango de importe","Como se distribuyen los SATs por rango de importe?","COUNT de DOCCAB TIPO=2 por rango de IMPORTETOTAL.","SELECT CASE WHEN IMPORTETOTAL=0 THEN 'Cero' WHEN IMPORTETOTAL<100 THEN '<100' WHEN IMPORTETOTAL<500 THEN '100-500' WHEN IMPORTETOTAL<1000 THEN '500-1k' WHEN IMPORTETOTAL<5000 THEN '1k-5k' ELSE '>5k' END AS RANGO, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 GROUP BY RANGO ORDER BY TOTAL DESC","SAT / Tecnico","Tecnico","Financiero","Medio","",""),
    q("sx_079","SATs por rango de numero de lineas","Como se distribuyen los SATs por numero de lineas?","COUNT de DOCCAB TIPO=2 por rango de lineas en DOCLIN.","SELECT CASE WHEN N_LINEAS=0 THEN 'Sin lineas' WHEN N_LINEAS=1 THEN '1 linea' WHEN N_LINEAS<=3 THEN '2-3 lineas' WHEN N_LINEAS<=5 THEN '4-5 lineas' WHEN N_LINEAS<=10 THEN '6-10 lineas' ELSE '>10 lineas' END AS RANGO, COUNT(*) AS N_SATS FROM (SELECT D.CODIGO, COUNT(L.CODARTICULO) AS N_LINEAS FROM DOCCAB D LEFT JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=2 GROUP BY D.CODIGO) GROUP BY RANGO ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_080","SATs por rango de dias pendientes","Como se distribuyen los SATs pendientes por antiguedad?","COUNT de DOCCAB TIPO=2 con ESTADO=0 por rango de dias pendientes.","SELECT CASE WHEN CAST(JULIANDAY('now')-JULIANDAY(FECHA) AS INTEGER)<=7 THEN '0-7 dias' WHEN CAST(JULIANDAY('now')-JULIANDAY(FECHA) AS INTEGER)<=30 THEN '8-30 dias' WHEN CAST(JULIANDAY('now')-JULIANDAY(FECHA) AS INTEGER)<=60 THEN '31-60 dias' WHEN CAST(JULIANDAY('now')-JULIANDAY(FECHA) AS INTEGER)<=90 THEN '61-90 dias' ELSE '>90 dias' END AS RANGO, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND (ESTADO=0 OR ESTADO IS NULL) AND FECHA IS NOT NULL GROUP BY RANGO ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Riesgo","Critico","",""),
    q("sx_081","SATs por rango de dias hasta cierre","Cuanto tardan en cerrarse los SATs?","Dias entre FECHA y fecha de cierre en DOCCAB TIPO=2 con ESTADO=1.","SELECT CASE WHEN CAST(JULIANDAY('now')-JULIANDAY(FECHA) AS INTEGER)<=7 THEN '0-7 dias' WHEN CAST(JULIANDAY('now')-JULIANDAY(FECHA) AS INTEGER)<=30 THEN '8-30 dias' WHEN CAST(JULIANDAY('now')-JULIANDAY(FECHA) AS INTEGER)<=60 THEN '31-60 dias' WHEN CAST(JULIANDAY('now')-JULIANDAY(FECHA) AS INTEGER)<=90 THEN '61-90 dias' ELSE '>90 dias' END AS RANGO, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND ESTADO=1 AND FECHA IS NOT NULL GROUP BY RANGO ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Medio","",""),
    q("sx_082","SATs por anio y agente (tabla cruzada)","Como evoluciona la carga de SATs por agente en cada anio?","COUNT de DOCCAB TIPO=2 por anio y agente.","SELECT SUBSTR(FECHA,1,4) AS ANIO, COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL AND CODAGENTE>0 GROUP BY SUBSTR(FECHA,1,4), CODAGENTE ORDER BY ANIO DESC, N_SATS DESC LIMIT 40","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_083","SATs por anio y cliente (tabla cruzada)","Como evoluciona la generacion de SATs por cliente en cada anio?","COUNT de DOCCAB TIPO=2 por anio y cliente.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, "+_C+" AS CLIENTE, COUNT(*) AS N_SATS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), D.CODCLIENTE ORDER BY ANIO DESC, N_SATS DESC LIMIT 60","SAT / Tecnico","Tecnico","Cliente","Alto","",""),
    q("sx_084","SATs por anio y articulo (tabla cruzada)","Como evoluciona la aparicion de articulos en SATs en cada anio?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 por anio y articulo.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), L.CODARTICULO ORDER BY ANIO DESC, N_SATS DESC LIMIT 60","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_085","SATs por anio y familia (tabla cruzada)","Como evoluciona la aparicion de familias en SATs en cada anio?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 por anio y familia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO WHERE D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), A.CODFAMILIA ORDER BY ANIO DESC, N_SATS DESC LIMIT 40","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_086","SATs por anio y proveedor (tabla cruzada)","Como evoluciona la aparicion de proveedores en SATs en cada anio?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 por anio y proveedor.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO WHERE D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), A.PROVEEDDEFECTO ORDER BY ANIO DESC, N_SATS DESC LIMIT 40","SAT / Tecnico","Tecnico","Proveedor","Alto","",""),
    q("sx_087","SATs por anio y estado (tabla cruzada)","Como evoluciona el estado de los SATs en cada anio?","COUNT de DOCCAB TIPO=2 por anio y estado.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE WHEN ESTADO=1 THEN 'Cerrado' ELSE 'Pendiente' END AS ESTADO_SAT, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), ESTADO ORDER BY ANIO DESC, N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_088","SATs por anio y forma de pago (tabla cruzada)","Como evoluciona la forma de pago de los SATs en cada anio?","COUNT de DOCCAB TIPO=2 por anio y forma de pago.","SELECT SUBSTR(FECHA,1,4) AS ANIO, COALESCE(CODFORMAPAGO,'Sin forma pago') AS FORMA_PAGO, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), CODFORMAPAGO ORDER BY ANIO DESC, N_SATS DESC LIMIT 30","SAT / Tecnico","Tecnico","Financiero","Bajo","",""),
    q("sx_089","SATs por anio y codigo postal (tabla cruzada)","Como evoluciona la distribucion geografica de SATs en cada anio?","COUNT de DOCCAB TIPO=2 por anio y codigo postal del cliente.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_SATS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), C.CP ORDER BY ANIO DESC, N_SATS DESC LIMIT 40","SAT / Tecnico","Tecnico","Geografico","Medio","",""),
    q("sx_090","SATs por anio y rango de importe (tabla cruzada)","Como evoluciona la distribucion de SATs por importe en cada anio?","COUNT de DOCCAB TIPO=2 por anio y rango de importe.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE WHEN IMPORTETOTAL=0 THEN 'Cero' WHEN IMPORTETOTAL<100 THEN '<100' WHEN IMPORTETOTAL<500 THEN '100-500' WHEN IMPORTETOTAL<1000 THEN '500-1k' WHEN IMPORTETOTAL<5000 THEN '1k-5k' ELSE '>5k' END AS RANGO, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), RANGO ORDER BY ANIO DESC, N_SATS DESC LIMIT 40","SAT / Tecnico","Tecnico","Financiero","Medio","",""),
    q("sx_091","SATs por anio y mes (tabla cruzada)","Como evoluciona la generacion de SATs mes a mes en cada anio?","COUNT de DOCCAB TIPO=2 por anio y mes.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CAST(SUBSTR(FECHA,6,2) AS INTEGER) AS MES, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), CAST(SUBSTR(FECHA,6,2) AS INTEGER) ORDER BY ANIO DESC, MES ASC LIMIT 60","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_092","SATs por anio y trimestre (tabla cruzada)","Como evoluciona la generacion de SATs trimestre a trimestre en cada anio?","COUNT de DOCCAB TIPO=2 por anio y trimestre.","SELECT SUBSTR(FECHA,1,4) AS ANIO, ((CAST(SUBSTR(FECHA,6,2) AS INTEGER)-1)/3+1) AS TRIMESTRE, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), TRIMESTRE ORDER BY ANIO DESC, TRIMESTRE ASC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_093","SATs por anio y dia de la semana (tabla cruzada)","Como evoluciona la generacion de SATs por dia de la semana en cada anio?","COUNT de DOCCAB TIPO=2 por anio y dia de la semana.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE CAST(strftime('%w',FECHA) AS INTEGER) WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Lunes' WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miercoles' WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' ELSE 'Sabado' END AS DIA, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), strftime('%w',FECHA) ORDER BY ANIO DESC, N_SATS DESC LIMIT 40","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_094","SATs por anio y numero de lineas (tabla cruzada)","Como evoluciona la complejidad de SATs por numero de lineas en cada anio?","COUNT de DOCCAB TIPO=2 por anio y rango de lineas.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, CASE WHEN COUNT(L.CODARTICULO)=0 THEN 'Sin lineas' WHEN COUNT(L.CODARTICULO)=1 THEN '1 linea' WHEN COUNT(L.CODARTICULO)<=3 THEN '2-3 lineas' WHEN COUNT(L.CODARTICULO)<=5 THEN '4-5 lineas' ELSE '>5 lineas' END AS RANGO_LINEAS, COUNT(DISTINCT D.CODIGO) AS N_SATS FROM DOCCAB D LEFT JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=2 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), D.CODIGO ORDER BY ANIO DESC LIMIT 40","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_095","SATs por anio y provincia (tabla cruzada)","Como evoluciona la distribucion provincial de SATs en cada anio?","COUNT de DOCCAB TIPO=2 por anio y provincia del cliente.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_SATS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), C.CP ORDER BY ANIO DESC, N_SATS DESC LIMIT 40","SAT / Tecnico","Tecnico","Geografico","Medio","",""),
    q("sx_096","SATs por anio y semestre (tabla cruzada)","Como evoluciona la generacion de SATs semestre a semestre en cada anio?","COUNT de DOCCAB TIPO=2 por anio y semestre.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE WHEN CAST(SUBSTR(FECHA,6,2) AS INTEGER)<=6 THEN 1 ELSE 2 END AS SEMESTRE, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), SEMESTRE ORDER BY ANIO DESC, SEMESTRE ASC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Medio","",""),
    q("sx_097","SATs por anio y mes del anio (estacionalidad)","Que meses del anio se generan mas SATs historicamente?","COUNT de DOCCAB TIPO=2 por mes del anio (1-12) en toda la historia.","SELECT CAST(strftime('%m',FECHA) AS INTEGER) AS MES_NUM, CASE CAST(strftime('%m',FECHA) AS INTEGER) WHEN 1 THEN 'Enero' WHEN 2 THEN 'Febrero' WHEN 3 THEN 'Marzo' WHEN 4 THEN 'Abril' WHEN 5 THEN 'Mayo' WHEN 6 THEN 'Junio' WHEN 7 THEN 'Julio' WHEN 8 THEN 'Agosto' WHEN 9 THEN 'Septiembre' WHEN 10 THEN 'Octubre' WHEN 11 THEN 'Noviembre' ELSE 'Diciembre' END AS MES_NOMBRE, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY MES_NUM ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Medio","",""),
    q("sx_098","SATs por anio y trimestre del anio (estacionalidad)","Que trimestres del anio se generan mas SATs historicamente?","COUNT de DOCCAB TIPO=2 por trimestre del anio (1-4) en toda la historia.","SELECT ((CAST(SUBSTR(FECHA,6,2) AS INTEGER)-1)/3+1) AS TRIMESTRE, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY TRIMESTRE ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Medio","",""),
    q("sx_099","SATs por anio y semestre del anio (estacionalidad)","Que semestres del anio se generan mas SATs historicamente?","COUNT de DOCCAB TIPO=2 por semestre del anio (1-2) en toda la historia.","SELECT CASE WHEN CAST(SUBSTR(FECHA,6,2) AS INTEGER)<=6 THEN 1 ELSE 2 END AS SEMESTRE, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SEMESTRE ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_100","SATs por anio y dia de la semana (estacionalidad)","Que dias de la semana se generan mas SATs historicamente?","COUNT de DOCCAB TIPO=2 por dia de la semana en toda la historia.","SELECT CASE CAST(strftime('%w',FECHA) AS INTEGER) WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Lunes' WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miercoles' WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' ELSE 'Sabado' END AS DIA, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY strftime('%w',FECHA) ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_101","SATs por anio y hora del dia (estacionalidad)","A que horas del dia se generan mas SATs historicamente?","COUNT de DOCCAB TIPO=2 por hora del dia en toda la historia.","SELECT CAST(strftime('%H',FECHA) AS INTEGER) AS HORA, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY HORA ORDER BY HORA","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_102","SATs por anio y dia del mes (estacionalidad)","Que dias del mes se generan mas SATs historicamente?","COUNT de DOCCAB TIPO=2 por dia del mes en toda la historia.","SELECT CAST(strftime('%d',FECHA) AS INTEGER) AS DIA_MES, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY DIA_MES ORDER BY N_SATS DESC LIMIT 31","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_103","SATs por anio y semana del anio (estacionalidad)","Que semanas del anio se generan mas SATs historicamente?","COUNT de DOCCAB TIPO=2 por semana del anio en toda la historia.","SELECT CAST(strftime('%W',FECHA) AS INTEGER) AS SEMANA, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SEMANA ORDER BY N_SATS DESC LIMIT 52","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_104","SATs por anio y codigo postal del cliente (estacionalidad)","Que zonas geograficas generan mas SATs historicamente?","COUNT de DOCCAB TIPO=2 por codigo postal del cliente en toda la historia.","SELECT COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_SATS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 GROUP BY C.CP ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Geografico","Medio","",""),
    q("sx_105","SATs por anio y provincia del cliente (estacionalidad)","Que provincias generan mas SATs historicamente?","COUNT de DOCCAB TIPO=2 por provincia del cliente en toda la historia.","SELECT COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_SATS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 GROUP BY C.CP ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Geografico","Medio","",""),
    q("sx_106","SATs por anio y forma de pago (estacionalidad)","Que formas de pago se usan mas en SATs historicamente?","COUNT de DOCCAB TIPO=2 por forma de pago en toda la historia.","SELECT COALESCE(CODFORMAPAGO,'Sin forma pago') AS FORMA_PAGO, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 GROUP BY CODFORMAPAGO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Financiero","Bajo","",""),
    q("sx_107","SATs por anio y estado (estacionalidad)","Como se distribuyen los estados de SATs historicamente?","COUNT de DOCCAB TIPO=2 por estado en toda la historia.","SELECT CASE WHEN ESTADO=1 THEN 'Cerrado' ELSE 'Pendiente' END AS ESTADO_SAT, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 GROUP BY ESTADO ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_108","SATs por anio y rango de importe (estacionalidad)","Como se distribuyen los SATs por importe historicamente?","COUNT de DOCCAB TIPO=2 por rango de importe en toda la historia.","SELECT CASE WHEN IMPORTETOTAL=0 THEN 'Cero' WHEN IMPORTETOTAL<100 THEN '<100' WHEN IMPORTETOTAL<500 THEN '100-500' WHEN IMPORTETOTAL<1000 THEN '500-1k' WHEN IMPORTETOTAL<5000 THEN '1k-5k' ELSE '>5k' END AS RANGO, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 GROUP BY RANGO ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Financiero","Medio","",""),
    q("sx_109","SATs por anio y numero de lineas (estacionalidad)","Como se distribuyen los SATs por numero de lineas historicamente?","COUNT de DOCCAB TIPO=2 por rango de lineas en toda la historia.","SELECT CASE WHEN N_LINEAS=0 THEN 'Sin lineas' WHEN N_LINEAS=1 THEN '1 linea' WHEN N_LINEAS<=3 THEN '2-3 lineas' WHEN N_LINEAS<=5 THEN '4-5 lineas' WHEN N_LINEAS<=10 THEN '6-10 lineas' ELSE '>10 lineas' END AS RANGO, COUNT(*) AS N_SATS FROM (SELECT D.CODIGO, COUNT(L.CODARTICULO) AS N_LINEAS FROM DOCCAB D LEFT JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=2 GROUP BY D.CODIGO) GROUP BY RANGO ORDER BY N_SATS DESC","SAT / Tecnico","Tecnico","Operacional","Bajo","",""),
    q("sx_110","SATs por anio y agente (estacionalidad)","Como se distribuyen los SATs por agente historicamente?","COUNT de DOCCAB TIPO=2 por agente en toda la historia.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, COUNT(*) AS N_SATS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=2 AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Alto","",""),
    q("sx_111","SATs por anio y cliente (estacionalidad)","Como se distribuyen los SATs por cliente historicamente?","COUNT de DOCCAB TIPO=2 por cliente en toda la historia.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_SATS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 GROUP BY D.CODCLIENTE ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Cliente","Alto","",""),
    q("sx_112","SATs por anio y articulo (estacionalidad)","Como se distribuyen los SATs por articulo historicamente?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 por articulo en toda la historia.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO GROUP BY L.CODARTICULO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_113","SATs por anio y familia (estacionalidad)","Como se distribuyen los SATs por familia historicamente?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 por familia en toda la historia.","SELECT COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO GROUP BY A.CODFAMILIA ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Producto","Alto","",""),
    q("sx_114","SATs por anio y proveedor (estacionalidad)","Como se distribuyen los SATs por proveedor historicamente?","COUNT de DOCLIN JOIN DOCCAB TIPO=2 por proveedor en toda la historia.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_SATS DESC LIMIT 20","SAT / Tecnico","Tecnico","Proveedor","Alto","",""),
    q("sx_115","SATs por anio y ticket medio (estacionalidad)","Como evoluciona el ticket medio de SAT en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, ROUND(AVG(IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4) ORDER BY ANIO DESC","SAT / Tecnico","Tecnico","KPI","Medio","",""),
    q("sx_116","SATs por anio y ticket medio por agente (estacionalidad)","Como evoluciona el ticket medio de SAT por agente en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio y agente en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, ROUND(AVG(IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL AND CODAGENTE>0 GROUP BY SUBSTR(FECHA,1,4), CODAGENTE ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 40","SAT / Tecnico","Tecnico","KPI","Medio","",""),
    q("sx_117","SATs por anio y ticket medio por cliente (estacionalidad)","Como evoluciona el ticket medio de SAT por cliente en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio y cliente en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, "+_C+" AS CLIENTE, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_SATS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), D.CODCLIENTE ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 60","SAT / Tecnico","Tecnico","Cliente","Medio","",""),
    q("sx_118","SATs por anio y ticket medio por articulo (estacionalidad)","Como evoluciona el ticket medio de SAT por articulo en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio y articulo en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, "+_A+" AS ARTICULO, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), L.CODARTICULO ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 60","SAT / Tecnico","Tecnico","Producto","Medio","",""),
    q("sx_119","SATs por anio y ticket medio por familia (estacionalidad)","Como evoluciona el ticket medio de SAT por familia en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio y familia en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO WHERE D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), A.CODFAMILIA ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 40","SAT / Tecnico","Tecnico","Producto","Medio","",""),
    q("sx_120","SATs por anio y ticket medio por proveedor (estacionalidad)","Como evoluciona el ticket medio de SAT por proveedor en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio y proveedor en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_SATS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=2 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO WHERE D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), A.PROVEEDDEFECTO ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 40","SAT / Tecnico","Tecnico","Proveedor","Medio","",""),
    q("sx_121","SATs por anio y ticket medio por codigo postal (estacionalidad)","Como evoluciona el ticket medio de SAT por zona geografica en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio y codigo postal del cliente en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(C.CP,'Sin CP') AS CP, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_SATS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), C.CP ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 40","SAT / Tecnico","Tecnico","Geografico","Bajo","",""),
    q("sx_122","SATs por anio y ticket medio por provincia (estacionalidad)","Como evoluciona el ticket medio de SAT por provincia en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio y provincia del cliente en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(C.CP,'Sin provincia') AS PROVINCIA, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_SATS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=2 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), C.CP ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 40","SAT / Tecnico","Tecnico","Geografico","Bajo","",""),
    q("sx_123","SATs por anio y ticket medio por forma de pago (estacionalidad)","Como evoluciona el ticket medio de SAT por forma de pago en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio y forma de pago en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, COALESCE(CODFORMAPAGO,'Sin forma pago') AS FORMA_PAGO, ROUND(AVG(IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), CODFORMAPAGO ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 30","SAT / Tecnico","Tecnico","Financiero","Bajo","",""),
    q("sx_124","SATs por anio y ticket medio por estado (estacionalidad)","Como evoluciona el ticket medio de SAT por estado en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=2 por anio y estado en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE WHEN ESTADO=1 THEN 'Cerrado' ELSE 'Pendiente' END AS ESTADO_SAT, ROUND(AVG(IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_SATS FROM DOCCAB WHERE TIPO=2 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), ESTADO ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 20","SAT / Tecnico","Tecnico","KPI","Medio","",""),
    q("sx_125","Resumen ejecutivo de SAT","Cual es el resumen ejecutivo de los KPIs de SAT mas importantes?","Combina total SATs, pendientes, cerrados, ticket medio, importe total.","SELECT ROUND((SELECT COUNT(*) FROM DOCCAB WHERE TIPO=2),0) AS TOTAL_SATS, ROUND((SELECT COUNT(*) FROM DOCCAB WHERE TIPO=2 AND (ESTADO=0 OR ESTADO IS NULL)),0) AS PENDIENTES, ROUND((SELECT COUNT(*) FROM DOCCAB WHERE TIPO=2 AND ESTADO=1),0) AS CERRADOS, ROUND((SELECT AVG(IMPORTETOTAL) FROM DOCCAB WHERE TIPO=2),2) AS TICKET_MEDIO, ROUND((SELECT SUM(IMPORTETOTAL) FROM DOCCAB WHERE TIPO=2),2) AS IMPORTE_TOTAL, ROUND((SELECT SUM(IMPORTETOTAL) FROM DOCCAB WHERE TIPO=2 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now')),2) AS IMPORTE_MES_ACTUAL","SAT / Tecnico","Tecnico","KPI","Critico","Resumen ejecutivo SAT",""),
]
